var escape=value=>String(value??"\u2014").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]);var lap=ms=>Number.isFinite(ms)&&ms>0&&ms<2147483647?`${Math.floor(ms/6e4)}:${String(Math.floor(ms/1e3)%60).padStart(2,"0")}.${String(ms%1e3).padStart(3,"0")}`:"\u2014";function renderTeamResults(race,language="ru",{driverLink,driverAction}={}){const en=language==="en",tx=(ru,english)=>en?english:ru;if(!Array.isArray(race?.team_results))return`<p>${tx("\u041A\u043E\u043C\u0430\u043D\u0434\u043D\u044B\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B \u043E\u0431\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F.","Team results are being processed.")}</p>`;if(!race.team_results.length)return`<p class="site-empty">${tx("\u041A\u043E\u043C\u0430\u043D\u0434\u043D\u044B\u0445 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u043F\u043E\u043A\u0430 \u043D\u0435\u0442.","No team results yet.")}</p>`;const personal=new Map((race.results||[]).map(p=>[p.public_id,p]));return`<div class="table-wrap page-table-scroll"><table class="race-results-grid page-table results-table team-results-table"><thead><tr><th>#</th><th>${tx("\u041A\u043E\u043C\u0430\u043D\u0434\u0430 / \u044D\u043A\u0438\u043F\u0430\u0436","Team / crew")}</th><th>${tx("\u041C\u0430\u0448\u0438\u043D\u0430","Car")}</th><th>${tx("\u041A\u0440\u0443\u0433\u0438","Laps")}</th><th>${tx("\u041B\u0443\u0447\u0448\u0438\u0439 \u043A\u0440\u0443\u0433","Best lap")}</th><th>${tx("\u041E\u0447\u043A\u0438 \u043A\u043E\u043C\u0430\u043D\u0434\u044B","Team points")}</th>${driverAction?`<th>${tx("\u0420\u0435\u043F\u043E\u0440\u0442","Report")}</th>`:""}</tr></thead><tbody>${race.team_results.map(team=>`<tr${team.status==="classified"&&team.position>=1&&team.position<=3?` data-podium-place="${escape(team.position)}"`:""}><td>${escape(team.position??team.status)}</td><td><strong>${escape(team.team_name)}</strong> \xB7 #${escape(team.race_number)}${(team.drivers||[]).map(pilot=>{const p=pilot.personal_result||personal.get(pilot.public_id);const name=p?.driver||pilot.display_name||pilot.public_id;const details=p?`${tx("\u041E\u0447\u043A\u0438","Points")}: ${p.points??"\u2014"} \xB7 \u0394Elo ${p.elo_rating_delta??"\u2014"} \xB7 SR ${p.safety_rating_after??p.safety_rating??p.safety_after??"\u2014"}`:pilot.participated?tx("\u0415\u0445\u0430\u043B","Drove"):tx("\u041D\u0435 \u0435\u0445\u0430\u043B","Did not drive");const linkedName=driverLink?driverLink({public_id:pilot.public_id,driver:name}):`<a class="driver-link" href="${en?"/driver/":"/ru/driver/"}?id=${encodeURIComponent(pilot.public_id)}">${escape(name)}</a>`;return`<div class="race-note">${linkedName} \xB7 ${escape(details)}</div>`}).join("")}</td><td>${escape(team.car_name||`ACC #${team.car_model}`)}</td><td>${escape(team.lap_count)}</td><td>${escape(team.best_lap||lap(team.best_lap_ms))}</td><td>${escape(team.points??0)}</td>${driverAction?`<td class="report-action-cell">${(team.drivers||[]).map(p=>`<div class="race-note">${escape(p.display_name||personal.get(p.public_id)?.driver||tx("\u041F\u0438\u043B\u043E\u0442","Driver"))} \xB7 ${driverAction(p)}</div>`).join("")}</td>`:""}</tr>`).join("")}</tbody></table></div>`}export{renderTeamResults};
